<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import {useUserStoreHook} from '@/store/modules/user';import {request} from './service';import LinIcon from './LinIcon.vue';import './space.scss';import './space-v8.scss';
const route=useRoute(),me=useUserStoreHook(),theme=ref('minimal'),wallpaper=ref('/assets/landscape-study.webp'),opacity=ref(.24),motion=ref(true),open=ref(false),notice=ref('');
const groups=[['/room','我的房间','home'],['/article/articleList','创作','pen'],['/life/library','兴趣收藏','heart'],['/life/tasks','日常','clock'],['/management','管理','settings']];const adminPaths=['/management','/comments','/registrations','/taxonomy','/authors','/site-settings','/appearance','/life/settings'];
const section=computed(()=>route.path.startsWith('/article')||['/moments','/albums'].includes(route.path)?'创作':adminPaths.includes(route.path)?'管理':route.path==='/life/library'?'兴趣收藏':route.path.startsWith('/life')?'日常':route.path==='/profile'?'个人设置':'我的房间');
const sub=computed(()=>section.value==='创作'?[['/article/articleList','文章'],['/article/addArticle','写文章'],['/moments','说说'],['/albums','相册']]:section.value==='管理'?[['/management','管理概览'],['/comments','评论审核'],['/registrations','注册审核'],['/taxonomy','分类标签'],['/authors','读者账号'],['/site-settings','博客设置'],['/appearance','空间外观'],['/life/settings','日常偏好']]:[]);
async function load(){const p=await request('/api/studio/profile');theme.value=p.theme;wallpaper.value=p.customWallpaper||'/assets/'+p.wallpaper+'.webp';opacity.value=(p.wallpaperOpacity??24)/100;motion.value=p.motion!==false;}
async function toggle(){try{const p=await request('/api/studio/profile');p.theme=theme.value==='cozy'?'minimal':'cozy';await request('/api/studio/profile','PUT',p);theme.value=p.theme;window.dispatchEvent(new CustomEvent('lin-theme',{detail:p.theme}));}catch(e){notice.value=e.message;}}
watch(()=>route.path,()=>appearance());
function changed(e){theme.value=e.detail;}function appearance(){load().catch(e=>notice.value=e.message);}onMounted(()=>{appearance();addEventListener('lin-theme',changed);addEventListener('lin-appearance',appearance);});onBeforeUnmount(()=>{removeEventListener('lin-theme',changed);removeEventListener('lin-appearance',appearance);});
</script>
<template><div class="space-shell" :data-theme="theme" :data-motion="motion" :style="{'--room-wallpaper':'url('+wallpaper+')','--wallpaper-opacity':opacity}"><header class="space-bar"><RouterLink to="/room" class="space-logo"><span>L✦</span><div>{{me.nick_name||'Lin'}} 的{{theme==='cozy'?'私宅':'工作室'}}<small>{{theme==='cozy'?'SAVE POINT / 私人存档点':'STUDIO / 简约工作室'}}</small></div></RouterLink><button class="space-nav-toggle" @click="open=!open" aria-label="展开空间导航"><LinIcon name="menu"/></button><nav :class="{open}"><RouterLink v-for="[path,label,icon] in groups" :key="path" :to="path" :class="{selected:section===label}" @click="open=false"><LinIcon :name="icon" :size="17"/>{{label}}</RouterLink></nav><div class="space-controls"><button @click="toggle" class="space-theme">{{theme==='cozy'?'✦ 私宅':'◻ 简约'}}</button><RouterLink to="/profile" aria-label="个人设置"><img :src="me.avatar||'/favicon.svg'" alt="我的头像"/></RouterLink><a href="/" class="space-public">公开博客 ↗</a></div></header><div class="space-context"><span>我的空间 <i>/</i> {{section}} </span><div><RouterLink v-if="section!=='管理'" to="/appearance">空间外观</RouterLink><button @click="me.logOut()">退出</button></div></div><nav v-if="sub.length" class="space-subnav"><RouterLink v-for="[path,label] in sub" :key="path" :to="path" :class="{current:route.path===path}">{{label}}</RouterLink></nav><p v-if="notice" role="status">{{notice}}</p><main class="space-body admin-content"><RouterView v-slot="{Component}"><Transition name="room-page" mode="out-in"><component :is="Component" :key="route.fullPath"/></Transition></RouterView></main><footer class="space-bottom">KEEP YOUR SAVE FILE. <span>认真喜欢，也好好生活。</span><a href="/about">关于</a></footer></div></template>
